#!/usr/bin/env python3
"""Scratch tooling for the spring-quarter shipped-orders reconciliation.

Not a deliverable. Subcommands:
  fetch-orders   walk every /orders page, save raw JSON per page
  fetch-customers  fetch (and cache) each customer referenced by an order
"""
import http.client
import json
import os
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
DATA = "/tmp/recon/data"
LOGFILE = os.path.join(DATA, "events.log")
MAX_ATTEMPTS = 60          # per logical request, across all kinds of retry
MAX_CONSECUTIVE_AUTH = 5   # guard against a token that is rejected immediately


def log(msg):
    ts = datetime.now(timezone.utc).strftime("%H:%M:%S.%f")[:-3]
    os.makedirs(DATA, exist_ok=True)
    with open(LOGFILE, "a") as f:
        f.write(f"{ts} {msg}\n")


class Client:
    def __init__(self):
        self.token = None
        self.stats = {"requests": 0, "ok": 0, "429": 0, "auth_fail": 0,
                      "5xx": 0, "net_err": 0, "tokens": 0, "waited_s": 0.0}

    def _raw(self, method, path, auth):
        req = urllib.request.Request(BASE + path, method=method,
                                     data=(b"" if method == "POST" else None))
        if auth and self.token:
            req.add_header("Authorization", "Bearer " + self.token)
        self.stats["requests"] += 1
        try:
            with urllib.request.urlopen(req, timeout=20) as r:
                return r.status, r.headers, r.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read()

    def refresh_token(self):
        _, data = self.request("POST", "/token", auth=False)
        tok = data.get("token") if isinstance(data, dict) else None
        if not tok:
            raise RuntimeError(f"no token in /token response: {data!r}")
        self.token = tok
        self.stats["tokens"] += 1
        log(f"token refreshed -> {tok}")

    @staticmethod
    def _retry_after(headers, body):
        ra = headers.get("Retry-After")
        if ra is not None:
            try:
                return float(ra)
            except ValueError:
                pass
        try:
            v = json.loads(body).get("retry_after")
            if v is not None:
                return float(v)
        except Exception:
            pass
        return None

    def request(self, method, path, auth=True, allow_404=False):
        """Return (status, parsed_json). Retries 429/auth/5xx/network errors.

        404 is returned (not retried) only when allow_404 is set.
        Anything unrecognised is logged in full and raised, never guessed at.
        """
        auth_fails = 0
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if auth and self.token is None:
                self.refresh_token()
            try:
                status, headers, body = self._raw(method, path, auth)
            except (urllib.error.URLError, http.client.HTTPException, OSError) as e:
                self.stats["net_err"] += 1
                log(f"{method} {path} network error {e!r}; retry (attempt {attempt})")
                time.sleep(min(attempt, 10))
                continue

            if status == 200:
                try:
                    data = json.loads(body)
                except ValueError:
                    log(f"{method} {path} 200 but body is not JSON ({body[:200]!r}); retry")
                    time.sleep(0.5)
                    continue
                self.stats["ok"] += 1
                return 200, data

            text = body[:300].decode("utf-8", "replace")

            if status == 429:
                wait = self._retry_after(headers, body)
                if wait is None:
                    wait = min(attempt, 10)
                    log(f"{method} {path} 429 with no retry hint; fallback wait {wait}s: {text}")
                else:
                    log(f"{method} {path} 429 -> waiting {wait}s (Retry-After): {text}")
                self.stats["429"] += 1
                self.stats["waited_s"] += wait + 0.1
                time.sleep(wait + 0.1)
                continue

            if status in (401, 403) and auth:
                auth_fails += 1
                self.stats["auth_fail"] += 1
                log(f"{method} {path} -> {status} (token rejected) body={text!r} "
                    f"hdrs={dict(headers)}; fetching a new token")
                if auth_fails > MAX_CONSECUTIVE_AUTH:
                    raise RuntimeError(f"token rejected {auth_fails} times in a row on {path}")
                self.token = None
                continue

            if status == 404 and allow_404:
                try:
                    data = json.loads(body)
                except ValueError:
                    data = {"raw": text}
                return 404, data

            if status >= 500:
                self.stats["5xx"] += 1
                log(f"{method} {path} -> {status} body={text!r}; retry (attempt {attempt})")
                time.sleep(min(attempt, 10))
                continue

            log(f"{method} {path} -> UNEXPECTED {status} body={text!r} hdrs={dict(headers)}")
            raise RuntimeError(f"unexpected status {status} for {method} {path}: {text}")

        raise RuntimeError(f"gave up on {method} {path} after {MAX_ATTEMPTS} attempts")


ORDER_KEYS = {"id", "customer_id", "status", "placed_at", "amount_cents"}


def validate_page(data, page):
    problems = []
    if not isinstance(data, dict):
        raise RuntimeError(f"page {page}: body is not an object: {str(data)[:200]}")
    for k in ("page", "total_pages", "items", "next"):
        if k not in data:
            raise RuntimeError(f"page {page}: missing key {k!r}; keys={sorted(data)}")
    if data["page"] != page:
        raise RuntimeError(f"page {page}: server says page={data['page']!r}")
    if not isinstance(data["items"], list):
        raise RuntimeError(f"page {page}: items is not a list")
    for i, it in enumerate(data["items"]):
        if not isinstance(it, dict) or set(it) != ORDER_KEYS:
            problems.append(f"item {i}: keys={sorted(it) if isinstance(it, dict) else type(it)}")
    if problems:
        log(f"page {page}: item-shape oddities: {problems[:5]} (+{max(0, len(problems) - 5)} more)")
    return problems


def fetch_orders(c):
    pages_dir = os.path.join(DATA, "pages")
    os.makedirs(pages_dir, exist_ok=True)
    page, total = 1, None
    while total is None or page <= total:
        fp = os.path.join(pages_dir, f"page_{page:03d}.json")
        if os.path.exists(fp):
            with open(fp) as f:
                data = json.load(f)
            src = "cache"
        else:
            _, data = c.request("GET", f"/orders?page={page}")
            validate_page(data, page)
            tmp = fp + ".tmp"
            with open(tmp, "w") as f:
                json.dump(data, f)
            os.replace(tmp, fp)
            src = "fetched"
        if total is None:
            total = data["total_pages"]
        elif data["total_pages"] != total:
            log(f"page {page}: total_pages changed {total} -> {data['total_pages']}")
        want_next = f"/orders?page={page + 1}" if page < total else None
        if data["next"] != want_next:
            log(f"page {page}: next={data['next']!r}, expected {want_next!r}")
        print(f"page {page:>2}/{total} {src:<7} items={len(data['items'])} next={data['next']!r}", flush=True)
        page += 1
    print("stats:", c.stats, flush=True)


def main():
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    c = Client()
    if cmd == "fetch-orders":
        fetch_orders(c)
    else:
        print(__doc__)
        sys.exit(2)


if __name__ == "__main__":
    main()

