import http.client
import json
import os
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
DATA = "/tmp/recon/data"
LOGFILE = os.path.join(DATA, "events.log")
MAX_ATTEMPTS = 60          # per logical request, across all kinds of retry
MAX_CONSECUTIVE_AUTH = 5   # guard against a token that is rejected immediately


