            raise RuntimeError(f"no token in /token response: {data!r}")
        self.token = tok
        self.stats["tokens"] += 1
        log(f"token refreshed -> {tok}")

    @staticmethod
    def _retry_after(headers, body):
        ra = headers.get("Retry-After")
        if ra is not None:
            try:
                return float(ra)
            except ValueError:
                pass
        try:
            v = json.loads(body).get("retry_after")
            if v is not None:
                return float(v)
        except Exception:
            pass
        return None

