ORDER_KEYS = {"id", "customer_id", "status", "placed_at", "amount_cents"}


def validate_page(data, page):
    problems = []
    if not isinstance(data, dict):
        raise RuntimeError(f"page {page}: body is not an object: {str(data)[:200]}")
