            odd.append(s)
    print("placed_at formats:", dict(kinds), " other examples:", odd[:10])
    print("offsets seen:", dict(sorted(offsets.items())))
    print("amount types:", collections.Counter(type(it["amount_cents"]).__name__ for _, _, it in listings))
    amts = [it["amount_cents"] for _, _, it in listings if isinstance(it["amount_cents"], int)]
    print("amount min/max:", min(amts), max(amts), " non-positive:", sum(1 for a in amts if a <= 0))
    print("customer_id types:", collections.Counter(type(it["customer_id"]).__name__ for _, _, it in listings))
    cust = collections.Counter(it["customer_id"] for _, _, it in listings)
    print("distinct customers:", len(cust), " sample:", sorted(cust)[:5], "...", sorted(cust)[-5:])
    nums = sorted(int(k.split("-")[1]) for k in by_id if re.match(r"^ord-\d+$", k))
    print("order ids matching ord-N:", len(nums), " min/max:", nums[0], nums[-1],
