    print("ids not matching pattern:", [k for k in by_id if not re.match(r"^ord-\d+$", k)][:10])


START = datetime(2025, 3, 1, 0, 0, 0, tzinfo=timezone.utc)
END_EXCL = datetime(2025, 6, 1, 0, 0, 0, tzinfo=timezone.utc)   # 31 May 23:59:59.999.. is the last instant in


def utc_dt(s):
    dt = datetime.fromisoformat(s)          # py3.11 parses both 'Z' and +HH:MM
    if dt.tzinfo is None:
        raise ValueError(f"naive timestamp, refusing to guess a zone: {s!r}")
    return dt.astimezone(timezone.utc)


def dedup_orders(dirname="pages"):
    """Distinct orders keyed by id (first listing wins; repeats must be identical)."""
    listings = load_listings(dirname)
    seen, dups = {}, 0
    for _, _, it in listings:
        if it["id"] in seen:
            if seen[it["id"]] != it:
                raise RuntimeError(f"conflicting repeat listing for {it['id']}")
            dups += 1
        else:
            seen[it["id"]] = it
    return seen, dups, len(listings)


def qualifying(orders):
    return [o for o in orders.values()
            if o["status"] == "shipped" and START <= utc_dt(o["placed_at"]) < END_EXCL]


def fetch_customers(c):
    orders, _, _ = dedup_orders()
    ids = sorted({o["customer_id"] for o in qualifying(orders)})
    cdir = os.path.join(DATA, "customers")
    os.makedirs(cdir, exist_ok=True)
    print(f"{len(ids)} distinct customers behind qualifying orders", flush=True)
    for n, cid in enumerate(ids, 1):
        fp = os.path.join(cdir, f"{cid}.json")
        if os.path.exists(fp):
            continue
        status, data = c.request("GET", f"/customers/{cid}", allow_404=True)
        if status == 404:
            # make sure the 404 is stable before treating the id as unknown
            for _ in range(2):
                status, data = c.request("GET", f"/customers/{cid}", allow_404=True)
                if status != 404:
                    break
        tmp = fp + ".tmp"
        with open(tmp, "w") as f:
            json.dump({"status": status, "body": data}, f)
        os.replace(tmp, fp)
        print(f"  [{n}/{len(ids)}] {cid} -> {status}", flush=True)
    print("stats:", c.stats, flush=True)


def main():
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    c = Client()
    if cmd == "fetch-orders":
        fetch_orders(c)
    elif cmd == "inspect":
        inspect()
    elif cmd == "fetch-customers":
        fetch_customers(c)
    else:
        print(__doc__)
        sys.exit(2)


if __name__ == "__main__":
    main()

